const body = $input.first().json.body || $input.first().json;
if (!body.phone) {
  throw new Error('Missing required phone number for lead ticket creation');
}

const phone = String(body.phone).trim();
const name = body.name || 'WhatsApp Client';
const intent = body.intent || 'property_inquiry';
const propertyCode = body.propertyCode || body.listing_ref || '';
const budget = body.budget || 'Not specified';
const urgency = body.urgency || 'medium';
const message = body.message || '';
const notes = body.notes || '';

const priorityMap = {
  critical: 'Highest',
  high: 'High',
  medium: 'Medium',
  low: 'Low'
};

const summary = `[Lead] ${name} (${phone}) · ${intent.toUpperCase()}${propertyCode ? ' · ' + propertyCode : ''}`;

const adfDescription = {
  type: 'doc',
  version: 1,
  content: [
    {
      type: 'paragraph',
      content: [
        { type: 'text', text: 'Sierra Estates Lead Intake via n8n', marks: [{ type: 'strong' }] }
      ]
    },
    {
      type: 'bulletList',
      content: [
        {
          type: 'listItem',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Phone: ', marks: [{ type: 'strong' }] }, { type: 'text', text: phone }] }]
        },
        {
          type: 'listItem',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Name: ', marks: [{ type: 'strong' }] }, { type: 'text', text: name }] }]
        },
        {
          type: 'listItem',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Intent: ', marks: [{ type: 'strong' }] }, { type: 'text', text: intent }] }]
        },
        {
          type: 'listItem',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Property Code: ', marks: [{ type: 'strong' }] }, { type: 'text', text: propertyCode || 'N/A' }] }]
        },
        {
          type: 'listItem',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Budget: ', marks: [{ type: 'strong' }] }, { type: 'text', text: budget }] }]
        }
      ]
    },
    {
      type: 'paragraph',
      content: [{ type: 'text', text: 'Client Inquiry:', marks: [{ type: 'strong' }] }]
    },
    {
      type: 'blockquote',
      content: [{ type: 'paragraph', content: [{ type: 'text', text: message || 'No message text provided' }] }]
    }
  ]
};

return [{
  json: {
    summary,
    projectKey: body.projectKey || process.env.JIRA_PROJECT_KEY || 'SE',
    issueType: body.issueType || process.env.JIRA_ISSUE_TYPE || 'Task',
    priority: priorityMap[urgency] || 'Medium',
    labels: ['sierra-estates', 'lead-sync', 'n8n-workflow', intent.replace(/[^a-zA-Z0-9_-]/g, '-')],
    description: adfDescription,
    raw: body
  }
}];
